-- Original KLI reading and listening stimuli; academic review required before high-stakes use.
update public.assessment_tasks k set stimulus='My name is Lina. I live in Mataram and study English on Monday and Wednesday. I walk to class with my friend.',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='EN-A1-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='Hello, this is KLI. Your class starts at nine o’clock in Room Two. Please bring a notebook.',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='EN-A1-PLACEMENT' and k.skill='listening';
update public.assessment_tasks k set stimulus='Last weekend, Arif visited his aunt. They cooked lunch, talked about their family, and planned a trip for next month.',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='EN-A2-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='The library will close early on Friday because staff have a meeting. Please return borrowed books before three o’clock.',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='EN-A2-PLACEMENT' and k.skill='listening';
update public.assessment_tasks k set stimulus='Rani joined an online language exchange to improve her confidence. At first she spoke very little, but weekly conversations helped her explain ideas more clearly.',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='EN-B1-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='A student explains that a delayed bus caused them to miss the first lesson. They ask the teacher how to review the missed material.',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='EN-B1-PLACEMENT' and k.skill='listening';
update public.assessment_tasks k set stimulus='Flexible work can reduce commuting time, yet it may also blur the boundary between professional and personal life. Effective policies therefore balance autonomy with clear expectations.',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='EN-B2-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='A manager proposes changing the training schedule. They compare two options, acknowledge cost concerns, and recommend a short pilot program.',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='EN-B2-PLACEMENT' and k.skill='listening';
update public.assessment_tasks k set stimulus='Although digital assessment improves access and speed, its validity depends on task design, security, and interpretation. Efficiency alone cannot justify decisions that affect a learner’s future.',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='EN-C1-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='A researcher discusses mixed findings from a pilot study, identifies a limitation in the sample, and proposes collecting longitudinal evidence.',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='EN-C1-PLACEMENT' and k.skill='listening';
update public.assessment_tasks k set stimulus='A policy may be procedurally transparent yet substantively unfair when apparently neutral criteria reproduce existing disadvantages. Evaluation must therefore examine outcomes as well as intentions.',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='EN-C2-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='Two specialists debate whether predictive systems should guide high-stakes decisions. One emphasizes consistency; the other questions hidden assumptions and accountability.',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='EN-C2-PLACEMENT' and k.skill='listening';
update public.assessment_tasks k set stimulus='わたしはアニです。マタラムに住んでいます。月曜日と水曜日に日本語を勉強します。学校へバスで行きます。',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='JP-N5-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='こんにちは。あしたのクラスは九時からです。二番のへやに来てください。ノートを持ってきてください。',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='JP-N5-PLACEMENT' and k.skill='listening';
update public.assessment_tasks k set stimulus='先週の日曜日、リナさんは家族と海へ行きました。昼ごはんを食べて、写真をたくさん撮りました。来月も行く予定です。',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='JP-N4-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='金曜日は先生の会議があるので、図書館は三時に閉まります。本を借りたい人は早く来てください。',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='JP-N4-PLACEMENT' and k.skill='listening';
update public.assessment_tasks k set stimulus='アリさんは会話力を伸ばすために、オンライン交流会に参加しました。最初は緊張しましたが、毎週話すうちに自信がつきました。',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='JP-N3-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='学生はバスが遅れて授業の前半に出られなかった理由を説明し、復習方法を先生に相談しています。',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='JP-N3-PLACEMENT' and k.skill='listening';
update public.assessment_tasks k set stimulus='在宅勤務は通勤時間を減らす一方で、仕事と私生活の境界を曖昧にすることもある。そのため、柔軟性と明確なルールの両立が求められる。',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='JP-N2-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='担当者は研修日程の変更案を二つ比較し、費用への懸念を認めた上で、短期間の試行を提案しています。',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='JP-N2-PLACEMENT' and k.skill='listening';
update public.assessment_tasks k set stimulus='制度が手続き上は透明であっても、一見中立的な基準が既存の格差を再生産するなら、実質的な公正さが確保されたとは言い難い。',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='JP-N1-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='二人の専門家が重要な判断への予測システムの利用を議論し、一方は一貫性を、もう一方は説明責任と前提の妥当性を重視しています。',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='JP-N1-PLACEMENT' and k.skill='listening';
update public.assessment_tasks k set stimulus='Ich heiße Lina und wohne in Mataram. Am Montag und Mittwoch lerne ich Deutsch. Ich fahre mit dem Bus zum Kurs.',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='DE-A1-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='Guten Tag. Der Kurs beginnt morgen um neun Uhr in Raum zwei. Bitte bringen Sie ein Heft mit.',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='DE-A1-PLACEMENT' and k.skill='listening';
update public.assessment_tasks k set stimulus='Letzten Sonntag besuchte Arif seine Tante. Sie kochten zusammen, sprachen über die Familie und planten eine Reise für den nächsten Monat.',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='DE-A2-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='Am Freitag schließt die Bibliothek wegen einer Besprechung schon um drei Uhr. Bitte geben Sie Ihre Bücher vorher zurück.',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='DE-A2-PLACEMENT' and k.skill='listening';
update public.assessment_tasks k set stimulus='Rani nahm an einem Online-Sprachaustausch teil, um sicherer zu sprechen. Anfangs sagte sie wenig, doch die wöchentlichen Gespräche halfen ihr sehr.',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='DE-B1-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='Ein Student erklärt, dass ein verspäteter Bus ihn am pünktlichen Erscheinen hinderte, und fragt nach Material zum Nacharbeiten.',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='DE-B1-PLACEMENT' and k.skill='listening';
update public.assessment_tasks k set stimulus='Flexible Arbeit kann Pendelzeiten verringern, zugleich aber die Grenze zwischen Beruf und Privatleben verwischen. Gute Regeln verbinden daher Autonomie mit klaren Erwartungen.',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='DE-B2-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='Eine Leiterin vergleicht zwei neue Schulungspläne, räumt Kostenbedenken ein und empfiehlt zunächst eine kurze Testphase.',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='DE-B2-PLACEMENT' and k.skill='listening';
update public.assessment_tasks k set stimulus='Digitale Prüfungen verbessern zwar Zugang und Geschwindigkeit, ihre Validität hängt jedoch von Aufgabendesign, Sicherheit und verantwortungsvoller Interpretation ab.',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='DE-C1-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='Ein Forscher erläutert widersprüchliche Pilotdaten, benennt eine Einschränkung der Stichprobe und schlägt eine Langzeitstudie vor.',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='DE-C1-PLACEMENT' and k.skill='listening';
update public.assessment_tasks k set stimulus='Ein Verfahren kann formal transparent und dennoch materiell ungerecht sein, wenn scheinbar neutrale Kriterien bestehende Benachteiligungen fortschreiben.',prompt='Read the text and state the main idea plus two supporting details.' from public.assessment_tests t where k.test_id=t.id and t.code='DE-C2-PLACEMENT' and k.skill='reading';
update public.assessment_tasks k set stimulus='Zwei Fachleute erörtern den Einsatz prognostischer Systeme bei weitreichenden Entscheidungen und wägen Konsistenz gegen Rechenschaftspflicht ab.',prompt='Listen twice and state the purpose plus two important details.' from public.assessment_tests t where k.test_id=t.id and t.code='DE-C2-PLACEMENT' and k.skill='listening';